"""Generate a bounded p1-only route program from retained waypoints; never executes it."""
import argparse,json
from pathlib import Path
p=Path(__file__).parent
ap=argparse.ArgumentParser();ap.add_argument('x',type=int);ap.add_argument('y',type=int);ap.add_argument('z',type=int);ap.add_argument('--steps',type=int,default=80);ap.add_argument('--out',default='route_batch.js');ap.add_argument('--reclaim',action='store_true');a=ap.parse_args()
r=json.loads((p/'return_route.json').read_text())['path'];i=r.index([a.x,a.y,a.z]);path=r[i:i+a.steps+1]
body=r'''
let current=start;const begun=Date.now();let issue=null;try{if(!start.equals(new Vec3(...route[0]))||!shell(start))throw Error('START_BODY_OR_SHELL');guard();bot.pathfinder.setGoal(null);bot.clearControlStates();if(RECLAIM&&mats()<10){const noFoes=()=>{const es=Object.values(bot.entities).filter(e=>['ghast','blaze','skeleton','wither_skeleton','magma_cube','hoglin','piglin_brute','small_fireball','fireball'].includes(e.name)&&e.position.distanceTo(bot.entity.position)<70).filter(e=>{if(e.name!=='magma_cube')return true;const d=e.position.distanceTo(bot.entity.position);const close=d<18&&e.position.y+Math.max(2.1,e.height||0)>bot.entity.position.y-3;if(!close)console.log('RECLAIM_MELEE_SCOPE',e.id,d,e.position.y,bot.entity.position.y);return close;});if(es.length)throw Error('RECLAIM_RANGE_FOE '+es.map(e=>e.id+':'+e.name));};noFoes();const before=mats();const positions=[start.offset(0,2,0),start.offset(1,2,0),...dirs.flatMap(d=>[start.plus(d).offset(0,1,0),start.plus(d)])].filter(v=>!routeFloors.has(v.toString())&&full(bot.blockAt(v))&&materials.includes(bot.blockAt(v)?.name));console.log('RECLAIM_VISIBLE_POSITIONS',positions.map(v=>v.toString()),before);for(const v of positions){noFoes();await cut(v);await ticks(6);}await ticks(8);console.log('RECLAIM_MATERIAL_POST',before,mats());}for(const a of route.slice(1)){if(Date.now()-begun>120000){console.log('NATURAL_TIME_BOUND');break}const p=new Vec3(...a);if(p.x===current.x&&p.z===current.z&&p.y!==current.y){console.log('VERTICAL_HANDOFF',current.toString(),p.toString());break}guard();const harvestCredit=[0,1].filter(y=>materials.includes(bot.blockAt(p.offset(0,y,0))?.name)).length;if(cost(p)>mats()+harvestCredit){console.log('AFFORDABLE_ENDPOINT_STOP',p.toString(),cost(p),mats(),harvestCredit);break}if(!full(bot.blockAt(p.offset(0,-1,0))))throw Error('FLOOR_CHANGED '+p+' '+bot.blockAt(p.offset(0,-1,0))?.name);if(p.y>current.y)await cut(current.offset(0,2,0));if(p.y<current.y)await cut(p.offset(0,2,0));for(const y of[1,0])await cut(p.offset(0,y,0));if(!cold(p))throw Error('TARGET_NOT_COLD '+p);await go(p);trace.push(p);current=p;}if(mats()<cost(current))throw Error('END_RESERVE '+mats()+'/'+cost(current));await seal(current);bot.chat('P1 RETURN actual '+current+' full'+shell(current)+' HP'+bot.health+' rod'+bot.inventory.items().filter(i=>i.name==='blaze_rod').reduce((s,i)=>s+i.count,0)+' steps'+(trace.length-1));}catch(e){issue=e.message;console.log('ISSUE',issue);try{if(!dead&&!lost){if(cold(current)&&mats()>=cost(current))await seal(current);else {for(const p of trace.slice().reverse())await go(p,true);await seal(start)}}}catch(r){console.log('RECOVERY_FAIL',r.message)}}finally{console.log('ROUTE_RESULT',JSON.stringify({issue,current:[current.x,current.y,current.z],steps:trace.length-1}));await finish()}
'''
s=(p/'shield_lib.js').read_text()+'\nconst route='+json.dumps(path)+';const RECLAIM='+str(a.reclaim).lower()+';const routeFloors=new Set('+json.dumps([str(tuple(v)) for v in []])+');\n'+body
s=s.replace('const routeFloors=new Set([]);','const routeFloors=new Set('+json.dumps([f"({v[0]}, {v[1]-1}, {v[2]})" for v in r])+');')
(p/a.out).write_text(s);print(json.dumps({'origin':path[0],'proposedEnd':path[-1],'proposedSteps':len(path)-1,'out':str(p/a.out)}))
